// Value: protects=Use Mac value writes the Mac value back; fails_when=wrong value written or marker kept; why_new=direct check of the reducer output; seam=none; no_claim=operation derivation
describe('applySyncDetailAction use-mac-value', () => {
  test('restores the Mac name, bumps the name revision and clears the row', () => {
    // Arrange
    const state = withMarker('name', {
      kind: 'conflict',
      localValue: 'Mine',
      serverValue: 'Theirs',
    })
    state.categories[1]!.name = 'Theirs'

    // Act
    applySyncDetailAction(
      state,
      { rowId: `${work}:name`, action: 'use-mac-value' },
      context,
    )

    // Assert
    expect(state.categories[1]!.name).toBe('Mine')
    expect(state.categories[1]!.fieldRevisions.name).toBe(1)
    expect(state.binding!.declined).toEqual({})
  })
})
